using Txt = EduVerse.Core.Catalog.Text;

namespace EduVerse.Core.Tutor;

/// <summary>A date of the life of a figure.</summary>
public sealed record DossierEvent(int Year, Txt Text);

/// <summary>A primary source or a reliable page to see the historical evidence (an external, checked link).</summary>
public sealed record DossierSource(Txt Title, string Site, string Url);

/// <summary>
/// The dossier of a figure: the life in dates, the discovery explained (with an original illustration drawn in the browser),
/// the historical evidence and where to see it, and a curious fact. Texts written from documented facts.
/// </summary>
public sealed record Dossier(string Figure, IReadOnlyList<DossierEvent> Timeline, Txt Discovery, Txt Evidence, Txt Fact, IReadOnlyList<DossierSource> Sources);

public static class Dossiers
{
    private static DossierEvent E(int year, string text) => new(year, Txt.Of(text));

    private static DossierSource S(string title, string site, string url) => new(Txt.Of(title), site, url);

    public static readonly IReadOnlyList<Dossier> All =
    [
        new("curie",
            [E(1867, "Born in Warsaw (Poland)|Nace en Varsovia (Polonia)|Naît à Varsovie (Pologne)|Neix a Varsòvia (Polònia)"), E(1891, "Moves to Paris to study at the Sorbonne|Se va a París a estudiar en la Sorbona|Part à Paris étudier à la Sorbonne|Se'n va a París a estudiar a la Sorbona"),
             E(1898, "Discovers polonium and radium with Pierre Curie|Descubre el polonio y el radio con Pierre Curie|Découvre le polonium et le radium avec Pierre Curie|Descobreix el poloni i el radi amb Pierre Curie"), E(1903, "Nobel Prize in Physics|Premio Nobel de Física|Prix Nobel de physique|Premi Nobel de Física"),
             E(1911, "Nobel Prize in Chemistry|Premio Nobel de Química|Prix Nobel de chimie|Premi Nobel de Química"), E(1934, "Dies in France|Muere en Francia|Meurt en France|Mor a França")],
            Txt.Of("Some atoms are unstable: they break apart and give off invisible radiation. Marie Curie measured this radiation very precisely and saw that some minerals gave off more than their uranium could explain. So there had to be new elements inside: she and Pierre found polonium and radium. She called the phenomenon radioactivity.|Algunos átomos son inestables: se rompen y emiten una radiación invisible. Marie Curie midió esa radiación con mucha precisión y vio que algunos minerales emitían más de lo que explicaba su uranio. Así que dentro tenía que haber elementos nuevos: ella y Pierre encontraron el polonio y el radio. Llamó al fenómeno radiactividad.|Certains atomes sont instables : ils se cassent et émettent un rayonnement invisible. Marie Curie a mesuré ce rayonnement avec une grande précision et a vu que certains minerais en émettaient plus que ce que leur uranium expliquait. Il devait donc y avoir de nouveaux éléments à l'intérieur : avec Pierre, elle a trouvé le polonium et le radium. Elle a appelé ce phénomène la radioactivité.|Alguns àtoms són inestables: es trenquen i emeten una radiació invisible. Marie Curie va mesurar aquesta radiació amb molta precisió i va veure que alguns minerals n'emetien més del que explicava el seu urani. Per tant, a dins hi havia d'haver elements nous: ella i Pierre van trobar el poloni i el radi. En va dir radioactivitat."),
            Txt.Of("The Nobel Foundation keeps the official record of her two prizes, with the reason for each one: the 1911 prize was for discovering radium and polonium and isolating radium.|La Fundación Nobel conserva el registro oficial de sus dos premios con el motivo de cada uno: el de 1911 fue por descubrir el radio y el polonio y aislar el radio.|La Fondation Nobel conserve le registre officiel de ses deux prix et leur motif : celui de 1911 récompense la découverte du radium et du polonium et l'isolement du radium.|La Fundació Nobel conserva el registre oficial dels seus dos premis amb el motiu de cadascun: el de 1911 va ser per descobrir el radi i el poloni i aïllar el radi."),
            Txt.Of("Her notebooks are still radioactive today: to look at them you have to sign a form and wear protection.|Sus cuadernos siguen siendo radiactivos hoy: para consultarlos hay que firmar un documento y llevar protección.|Ses cahiers sont encore radioactifs aujourd'hui : pour les consulter, il faut signer un document et porter une protection.|Els seus quaderns encara són radioactius avui: per consultar-los cal signar un document i portar protecció."),
            [S("Nobel Prize in Chemistry 1911: the official record|Premio Nobel de Química 1911: el registro oficial|Prix Nobel de chimie 1911 : la fiche officielle|Premi Nobel de Química 1911: el registre oficial", "NobelPrize.org", "https://www.nobelprize.org/prizes/chemistry/1911/marie-curie/facts/")]),
        new("leonardo",
            [E(1452, "Born in Vinci, near Florence|Nace en Vinci, cerca de Florencia|Naît à Vinci, près de Florence|Neix a Vinci, a prop de Florència"), E(1482, "Moves to Milan|Se traslada a Milán|S'installe à Milan|Es trasllada a Milà"),
             E(1498, "Finishes The Last Supper|Termina La última cena|Termine La Cène|Acaba El Sant Sopar"), E(1503, "Starts the Mona Lisa|Empieza la Gioconda|Commence La Joconde|Comença la Gioconda"),
             E(1516, "Goes to France, invited by King Francis I|Se va a Francia invitado por el rey Francisco I|Part en France, invité par le roi François Iᵉʳ|Se'n va a França convidat pel rei Francesc I"), E(1519, "Dies in Amboise (France)|Muere en Amboise (Francia)|Meurt à Amboise (France)|Mor a Amboise (França)")],
            Txt.Of("Leonardo observed everything: the flight of birds, the flow of water, the muscles of the body. He drew what he saw and imagined machines from it, like this flying machine with flapping wings. It could not fly (a person is not strong enough), but his method — observe, draw, test — is the method of science.|Leonardo lo observaba todo: el vuelo de los pájaros, el movimiento del agua, los músculos del cuerpo. Dibujaba lo que veía y a partir de ello imaginaba máquinas, como esta máquina voladora de alas batientes. No podía volar (una persona no tiene fuerza suficiente), pero su método —observar, dibujar, probar— es el método de la ciencia.|Léonard observait tout : le vol des oiseaux, le mouvement de l'eau, les muscles du corps. Il dessinait ce qu'il voyait et en tirait des machines, comme cette machine volante à ailes battantes. Elle ne pouvait pas voler (un humain n'est pas assez fort), mais sa méthode — observer, dessiner, essayer — est celle de la science.|Leonardo ho observava tot: el vol dels ocells, el moviment de l'aigua, els músculs del cos. Dibuixava el que veia i a partir d'això imaginava màquines, com aquesta màquina voladora d'ales batents. No podia volar (una persona no té prou força), però el seu mètode —observar, dibuixar, provar— és el mètode de la ciència."),
            Txt.Of("Thousands of his notebook pages survive. The Codex Arundel, in the British Library, gathers pages on geometry, mechanics and water, written in his mirror writing.|Se conservan miles de páginas de sus cuadernos. El Códice Arundel, en la British Library, reúne páginas sobre geometría, mecánica y agua, escritas con su escritura especular.|Des milliers de pages de ses carnets ont été conservées. Le Codex Arundel, à la British Library, rassemble des pages sur la géométrie, la mécanique et l'eau, dans son écriture en miroir.|Es conserven milers de pàgines dels seus quaderns. El Còdex Arundel, a la British Library, aplega pàgines sobre geometria, mecànica i aigua, escrites amb la seva escriptura de mirall."),
            Txt.Of("He often left works unfinished: he was always starting something new.|A menudo dejaba obras sin terminar: siempre estaba empezando algo nuevo.|Il laissait souvent ses œuvres inachevées : il commençait toujours quelque chose de nouveau.|Sovint deixava obres sense acabar: sempre començava alguna cosa nova."),
            [S("A page of the Codex Arundel (British Library)|Una página del Códice Arundel (British Library)|Une page du Codex Arundel (British Library)|Una pàgina del Còdex Arundel (British Library)", "Google Arts & Culture", "https://artsandculture.google.com/asset/the-codex-arundel-leonardo-da-vinci/VwEw9o_NaGCnVw")]),
        new("newton",
            [E(1643, "Born in Woolsthorpe (England)|Nace en Woolsthorpe (Inglaterra)|Naît à Woolsthorpe (Angleterre)|Neix a Woolsthorpe (Anglaterra)"), E(1665, "Plague closes Cambridge: at home he works on light, motion and calculus|La peste cierra Cambridge: en casa trabaja en la luz, el movimiento y el cálculo|La peste ferme Cambridge : chez lui, il travaille sur la lumière, le mouvement et le calcul|La pesta tanca Cambridge: a casa treballa en la llum, el moviment i el càlcul"),
             E(1672, "Presents his experiments on light and colours|Presenta sus experimentos sobre la luz y los colores|Présente ses expériences sur la lumière et les couleurs|Presenta els seus experiments sobre la llum i els colors"), E(1687, "Publishes the Principia|Publica los Principia|Publie les Principia|Publica els Principia"),
             E(1704, "Publishes Opticks|Publica la Óptica|Publie l'Optique|Publica l'Òptica"), E(1727, "Dies in London|Muere en Londres|Meurt à Londres|Mor a Londres")],
            Txt.Of("Newton passed white light through a glass prism and it spread into the colours of the rainbow; with a second prism the colours joined again into white. So white light is a mixture of colours. In the Principia he showed that one force, gravity, explains both a falling apple and the orbit of the Moon.|Newton hizo pasar luz blanca por un prisma de vidrio y se abrió en los colores del arcoíris; con un segundo prisma los colores volvían a juntarse en blanco. Así que la luz blanca es una mezcla de colores. En los Principia demostró que una sola fuerza, la gravedad, explica la caída de una manzana y la órbita de la Luna.|Newton a fait passer de la lumière blanche dans un prisme de verre : elle s'est étalée en couleurs de l'arc-en-ciel ; avec un second prisme, les couleurs se réunissaient en blanc. La lumière blanche est donc un mélange de couleurs. Dans les Principia, il a montré qu'une seule force, la gravitation, explique la chute d'une pomme et l'orbite de la Lune.|Newton va fer passar llum blanca per un prisma de vidre i es va obrir en els colors de l'arc de Sant Martí; amb un segon prisma els colors es tornaven a ajuntar en blanc. Per tant, la llum blanca és una barreja de colors. Als Principia va demostrar que una sola força, la gravetat, explica la caiguda d'una poma i l'òrbita de la Lluna."),
            Txt.Of("Cambridge University Library has digitised Newton's own copy of the first edition of the Principia (1687), full of his handwritten corrections for the second edition.|La Biblioteca de la Universidad de Cambridge ha digitalizado el ejemplar del propio Newton de la primera edición de los Principia (1687), lleno de correcciones a mano para la segunda edición.|La bibliothèque de l'université de Cambridge a numérisé l'exemplaire personnel de Newton de la première édition des Principia (1687), plein de corrections à la main pour la deuxième édition.|La Biblioteca de la Universitat de Cambridge ha digitalitzat l'exemplar del mateix Newton de la primera edició dels Principia (1687), ple de correccions a mà per a la segona edició."),
            Txt.Of("Newton was also the head of the Royal Mint, where he chased people who made false coins.|Newton también dirigió la Real Casa de la Moneda, donde persiguió a los falsificadores.|Newton a aussi dirigé la Monnaie royale, où il a poursuivi les faux-monnayeurs.|Newton també va dirigir la Reial Casa de la Moneda, on va perseguir els falsificadors."),
            [S("Newton's annotated copy of the Principia|El ejemplar anotado de los Principia de Newton|L'exemplaire annoté des Principia de Newton|L'exemplar anotat dels Principia de Newton", "Cambridge Digital Library", "https://cudl.lib.cam.ac.uk/view/PR-ADV-B-00039-00001")]),
        new("lovelace",
            [E(1815, "Born in London, daughter of Lord Byron|Nace en Londres, hija de lord Byron|Naît à Londres, fille de Lord Byron|Neix a Londres, filla de lord Byron"), E(1833, "Meets Charles Babbage and sees his calculating machine|Conoce a Charles Babbage y ve su máquina de calcular|Rencontre Charles Babbage et voit sa machine à calculer|Coneix Charles Babbage i veu la seva màquina de calcular"),
             E(1835, "Marries William King (later Earl of Lovelace)|Se casa con William King (luego conde de Lovelace)|Épouse William King (plus tard comte de Lovelace)|Es casa amb William King (després comte de Lovelace)"), E(1843, "Publishes her Notes on the Analytical Engine|Publica sus Notas sobre la máquina analítica|Publie ses Notes sur la machine analytique|Publica les seves Notes sobre la màquina analítica"),
             E(1852, "Dies in London, at 36|Muere en Londres, con 36 años|Meurt à Londres, à 36 ans|Mor a Londres, amb 36 anys")],
            Txt.Of("Babbage designed the Analytical Engine, a machine of gears that would read instructions from punched cards, like the looms of the time. Ada translated an article about it and added Notes three times longer. In Note G she wrote, step by step, how the machine could calculate Bernoulli numbers: an algorithm for a machine. She also saw that it could handle any symbols, not only numbers.|Babbage diseñó la máquina analítica, una máquina de engranajes que leería instrucciones de tarjetas perforadas, como los telares de la época. Ada tradujo un artículo sobre ella y añadió unas Notas tres veces más largas. En la Nota G escribió, paso a paso, cómo la máquina podría calcular los números de Bernoulli: un algoritmo para una máquina. También vio que podría trabajar con cualquier símbolo, no solo con números.|Babbage a conçu la machine analytique, une machine à engrenages qui lirait ses instructions sur des cartes perforées, comme les métiers à tisser de l'époque. Ada a traduit un article à son sujet et y a ajouté des Notes trois fois plus longues. Dans la Note G, elle a écrit pas à pas comment la machine pourrait calculer les nombres de Bernoulli : un algorithme pour une machine. Elle a aussi vu qu'elle pourrait manipuler n'importe quels symboles, pas seulement des nombres.|Babbage va dissenyar la màquina analítica, una màquina d'engranatges que llegiria instruccions de targetes perforades, com els telers de l'època. L'Ada en va traduir un article i hi va afegir unes Notes tres vegades més llargues. A la Nota G va escriure, pas a pas, com la màquina podria calcular els nombres de Bernoulli: un algorisme per a una màquina. També va veure que podria treballar amb qualsevol símbol, no només amb nombres."),
            Txt.Of("The 1843 publication, \"Sketch of the Analytical Engine\" with the Notes signed A.A.L., can be read today in full, including the famous table of Note G.|La publicación de 1843, «Sketch of the Analytical Engine», con las Notas firmadas A.A.L., se puede leer hoy completa, incluida la famosa tabla de la Nota G.|La publication de 1843, « Sketch of the Analytical Engine », avec les Notes signées A.A.L., se lit aujourd'hui en entier, y compris le célèbre tableau de la Note G.|La publicació de 1843, «Sketch of the Analytical Engine», amb les Notes signades A.A.L., es pot llegir avui sencera, inclosa la famosa taula de la Nota G."),
            Txt.Of("The programming language Ada, created in 1980, is named after her.|El lenguaje de programación Ada, creado en 1980, lleva su nombre.|Le langage de programmation Ada, créé en 1980, porte son nom.|El llenguatge de programació Ada, creat el 1980, porta el seu nom."),
            [S("Sketch of the Analytical Engine, with Ada Lovelace's Notes (1843)|«Sketch of the Analytical Engine», con las Notas de Ada Lovelace (1843)|« Sketch of the Analytical Engine », avec les Notes d'Ada Lovelace (1843)|«Sketch of the Analytical Engine», amb les Notes d'Ada Lovelace (1843)", "Project Gutenberg", "https://www.gutenberg.org/files/75107/75107-h/75107-h.htm")]),
        new("galileo",
            [E(1564, "Born in Pisa (Italy)|Nace en Pisa (Italia)|Naît à Pise (Italie)|Neix a Pisa (Itàlia)"), E(1609, "Builds an improved telescope|Construye un telescopio mejorado|Construit une lunette améliorée|Construeix un telescopi millorat"),
             E(1610, "Publishes Sidereus Nuncius: the moons of Jupiter|Publica el Sidereus Nuncius: las lunas de Júpiter|Publie le Sidereus Nuncius : les lunes de Jupiter|Publica el Sidereus Nuncius: les llunes de Júpiter"), E(1632, "Publishes the Dialogue on the two world systems|Publica el Diálogo sobre los dos sistemas del mundo|Publie le Dialogue sur les deux grands systèmes du monde|Publica el Diàleg sobre els dos sistemes del món"),
             E(1633, "Tried by the Inquisition|Juzgado por la Inquisición|Jugé par l'Inquisition|Jutjat per la Inquisició"), E(1642, "Dies near Florence|Muere cerca de Florencia|Meurt près de Florence|Mor a prop de Florència")],
            Txt.Of("Night after night in January 1610, Galileo drew Jupiter and some little \"stars\" next to it. The stars changed place but always stayed in a line near the planet: they were four moons going around Jupiter. It was the proof that not everything in the sky turns around the Earth.|Noche tras noche, en enero de 1610, Galileo dibujó Júpiter y unas pequeñas «estrellas» a su lado. Las estrellas cambiaban de sitio pero siempre seguían en línea cerca del planeta: eran cuatro lunas girando alrededor de Júpiter. Era la prueba de que no todo en el cielo gira alrededor de la Tierra.|Nuit après nuit, en janvier 1610, Galilée a dessiné Jupiter et de petites « étoiles » à côté. Elles changeaient de place mais restaient toujours alignées près de la planète : c'étaient quatre lunes tournant autour de Jupiter. C'était la preuve que tout, dans le ciel, ne tourne pas autour de la Terre.|Nit rere nit, el gener de 1610, Galileu va dibuixar Júpiter i unes petites «estrelles» al costat. Les estrelles canviaven de lloc però sempre seguien en línia a prop del planeta: eren quatre llunes girant al voltant de Júpiter. Era la prova que no tot al cel gira al voltant de la Terra."),
            Txt.Of("His drawings of Jupiter and its moons were printed in Sidereus Nuncius (The Starry Messenger), Venice, 1610. Copies of the original survive in libraries such as the Linda Hall Library.|Sus dibujos de Júpiter y sus lunas se imprimieron en el Sidereus Nuncius (El mensajero sideral), Venecia, 1610. Se conservan ejemplares originales en bibliotecas como la Linda Hall Library.|Ses dessins de Jupiter et de ses lunes ont été imprimés dans le Sidereus Nuncius (Le Messager céleste), Venise, 1610. Des exemplaires originaux sont conservés dans des bibliothèques comme la Linda Hall Library.|Els seus dibuixos de Júpiter i les seves llunes es van imprimir al Sidereus Nuncius (El missatger sideri), Venècia, 1610. Se'n conserven exemplars originals en biblioteques com la Linda Hall Library."),
            Txt.Of("The four big moons of Jupiter are still called the Galilean moons: Io, Europa, Ganymede and Callisto.|Las cuatro grandes lunas de Júpiter se siguen llamando lunas galileanas: Ío, Europa, Ganímedes y Calisto.|Les quatre grandes lunes de Jupiter s'appellent toujours les satellites galiléens : Io, Europe, Ganymède et Callisto.|Les quatre grans llunes de Júpiter encara s'anomenen llunes galileanes: Io, Europa, Ganimedes i Cal·listo."),
            [S("Sidereus Nuncius: Galileo's drawings of Jupiter's moons|Sidereus Nuncius: los dibujos de Galileo de las lunas de Júpiter|Sidereus Nuncius : les dessins de Galilée des lunes de Jupiter|Sidereus Nuncius: els dibuixos de Galileu de les llunes de Júpiter", "Linda Hall Library", "https://www.lindahall.org/experience/digital-exhibitions/sun-in-early-modernity/01-the-copernican-revolution/sidereus-nuncius/")]),
        new("darwin",
            [E(1809, "Born in Shrewsbury (England)|Nace en Shrewsbury (Inglaterra)|Naît à Shrewsbury (Angleterre)|Neix a Shrewsbury (Anglaterra)"), E(1831, "Leaves on HMS Beagle for five years|Parte en el HMS Beagle durante cinco años|Part sur le HMS Beagle pour cinq ans|Surt amb l'HMS Beagle durant cinc anys"),
             E(1835, "Visits the Galápagos Islands|Visita las islas Galápagos|Visite les îles Galápagos|Visita les illes Galápagos"), E(1859, "Publishes On the Origin of Species|Publica El origen de las especies|Publie De l'origine des espèces|Publica L'origen de les espècies"),
             E(1871, "Publishes The Descent of Man|Publica El origen del hombre|Publie La Filiation de l'homme|Publica L'origen de l'home"), E(1882, "Dies in Downe (England)|Muere en Downe (Inglaterra)|Meurt à Downe (Angleterre)|Mor a Downe (Anglaterra)")],
            Txt.Of("The finches of the Galápagos have different beaks: thick ones for cracking hard seeds, thin ones for catching insects. Darwin's idea: in each generation, the individuals best suited to where they live survive and have more young. Over very many generations, species change and new ones appear. This is evolution by natural selection.|Los pinzones de las Galápagos tienen picos distintos: gruesos para romper semillas duras, finos para atrapar insectos. La idea de Darwin: en cada generación, los individuos mejor adaptados a donde viven sobreviven y tienen más crías. A lo largo de muchísimas generaciones, las especies cambian y aparecen otras nuevas. Es la evolución por selección natural.|Les pinsons des Galápagos ont des becs différents : épais pour casser des graines dures, fins pour attraper des insectes. L'idée de Darwin : à chaque génération, les individus les mieux adaptés à leur milieu survivent et ont plus de petits. Au fil de très nombreuses générations, les espèces changent et de nouvelles apparaissent. C'est l'évolution par la sélection naturelle.|Els pinsans de les Galápagos tenen becs diferents: gruixuts per trencar llavors dures, prims per atrapar insectes. La idea de Darwin: a cada generació, els individus més ben adaptats al lloc on viuen sobreviuen i tenen més cries. Al llarg de moltíssimes generacions, les espècies canvien i n'apareixen de noves. És l'evolució per selecció natural."),
            Txt.Of("The first edition of On the Origin of Species (London, John Murray, 24 November 1859) can be seen page by page in a public domain copy at the Wellcome Collection.|La primera edición de El origen de las especies (Londres, John Murray, 24 de noviembre de 1859) se puede ver página a página en un ejemplar de dominio público de la Wellcome Collection.|La première édition de De l'origine des espèces (Londres, John Murray, 24 novembre 1859) se consulte page par page dans un exemplaire du domaine public de la Wellcome Collection.|La primera edició de L'origen de les espècies (Londres, John Murray, 24 de novembre de 1859) es pot veure pàgina a pàgina en un exemplar de domini públic de la Wellcome Collection."),
            Txt.Of("Darwin waited about twenty years before publishing his theory, collecting more and more evidence.|Darwin esperó unos veinte años antes de publicar su teoría, reuniendo cada vez más pruebas.|Darwin a attendu une vingtaine d'années avant de publier sa théorie, en rassemblant toujours plus de preuves.|Darwin va esperar uns vint anys abans de publicar la seva teoria, reunint cada cop més proves."),
            [S("On the Origin of Species, first edition (1859)|El origen de las especies, primera edición (1859)|De l'origine des espèces, première édition (1859)|L'origen de les espècies, primera edició (1859)", "Wellcome Collection", "https://wellcomecollection.org/works/ytv5whr6")]),
        new("cervantes",
            [E(1547, "Born in Alcalá de Henares|Nace en Alcalá de Henares|Naît à Alcalá de Henares|Neix a Alcalá de Henares"), E(1571, "Fights at Lepanto and loses the use of his left hand|Lucha en Lepanto y pierde el uso de la mano izquierda|Combat à Lépante et perd l'usage de sa main gauche|Lluita a Lepant i perd l'ús de la mà esquerra"),
             E(1575, "Captured by pirates: five years in Algiers|Capturado por piratas: cinco años en Argel|Capturé par des pirates : cinq ans à Alger|Capturat per pirates: cinc anys a Alger"), E(1605, "Publishes the first part of Don Quixote|Publica la primera parte del Quijote|Publie la première partie de Don Quichotte|Publica la primera part del Quixot"),
             E(1615, "Publishes the second part|Publica la segunda parte|Publie la seconde partie|Publica la segona part"), E(1616, "Dies in Madrid|Muere en Madrid|Meurt à Madrid|Mor a Madrid")],
            Txt.Of("Don Quixote is often called the first modern novel. An old gentleman reads so many books of knights that he believes he is one, and sees giants where there are only windmills. His squire Sancho sees the world as it is. Their conversations mix humour and wisdom, and the characters change as the story goes on.|El Quijote suele considerarse la primera novela moderna. Un viejo hidalgo lee tantos libros de caballerías que se cree caballero, y ve gigantes donde solo hay molinos de viento. Su escudero Sancho ve el mundo tal como es. Sus conversaciones mezclan humor y sabiduría, y los personajes cambian a lo largo de la historia.|Don Quichotte est souvent appelé le premier roman moderne. Un vieux gentilhomme lit tant de romans de chevalerie qu'il se croit chevalier, et voit des géants là où il n'y a que des moulins à vent. Son écuyer Sancho voit le monde tel qu'il est. Leurs conversations mêlent humour et sagesse, et les personnages évoluent au fil de l'histoire.|El Quixot sol considerar-se la primera novel·la moderna. Un vell gentilhome llegeix tants llibres de cavalleries que es creu cavaller, i veu gegants on només hi ha molins de vent. El seu escuder Sancho veu el món tal com és. Les seves converses barregen humor i saviesa, i els personatges canvien al llarg de la història."),
            Txt.Of("The first edition was printed in Madrid by Juan de la Cuesta in 1605. The Biblioteca Nacional de España keeps original copies and shows them online.|La primera edición la imprimió Juan de la Cuesta en Madrid en 1605. La Biblioteca Nacional de España conserva ejemplares originales y los muestra en línea.|La première édition a été imprimée à Madrid par Juan de la Cuesta en 1605. La Bibliothèque nationale d'Espagne en conserve des exemplaires originaux et les montre en ligne.|La primera edició la va imprimir Juan de la Cuesta a Madrid el 1605. La Biblioteca Nacional d'Espanya en conserva exemplars originals i els mostra en línia."),
            Txt.Of("Cervantes and Shakespeare died a few days apart, in April 1616: that is why 23 April is World Book Day.|Cervantes y Shakespeare murieron con pocos días de diferencia, en abril de 1616: por eso el 23 de abril es el Día del Libro.|Cervantes et Shakespeare sont morts à quelques jours d'écart, en avril 1616 : c'est pourquoi le 23 avril est la Journée mondiale du livre.|Cervantes i Shakespeare van morir amb pocs dies de diferència, l'abril de 1616: per això el 23 d'abril és el Dia del Llibre."),
            [S("Don Quixote, 1605 edition (Biblioteca Nacional de España)|El Quijote, edición de 1605 (Biblioteca Nacional de España)|Don Quichotte, édition de 1605 (Bibliothèque nationale d'Espagne)|El Quixot, edició de 1605 (Biblioteca Nacional d'Espanya)", "Google Arts & Culture", "https://artsandculture.google.com/asset/el-ingenioso-hidalgo-don-quijote-de-la-mancha-trans-the-ingenious-gentleman-don-quixote-of-la-mancha-biblioteca-nacional-de-espa%C3%B1a-miguel-de-cervantes-saavedra/bwFxLvLAhF3g-A")]),
        new("franklin",
            [E(1920, "Born in London|Nace en Londres|Naît à Londres|Neix a Londres"), E(1945, "PhD from Cambridge, on the structure of coal|Doctorado en Cambridge, sobre la estructura del carbón|Doctorat à Cambridge, sur la structure du charbon|Doctorat a Cambridge, sobre l'estructura del carbó"),
             E(1951, "Starts studying DNA with X-rays at King's College London|Empieza a estudiar el ADN con rayos X en el King's College de Londres|Commence à étudier l'ADN aux rayons X au King's College de Londres|Comença a estudiar l'ADN amb raigs X al King's College de Londres"), E(1952, "Photo 51|La Foto 51|La photo 51|La Foto 51"),
             E(1953, "Publishes her DNA results in Nature|Publica sus resultados sobre el ADN en Nature|Publie ses résultats sur l'ADN dans Nature|Publica els seus resultats sobre l'ADN a Nature"), E(1958, "Dies in London, at 37|Muere en Londres, con 37 años|Meurt à Londres, à 37 ans|Mor a Londres, amb 37 anys")],
            Txt.Of("When X-rays go through DNA fibres, they scatter and leave a pattern on photographic film. The X-shaped cross of Photo 51 is the signature of a helix, and the spacing of the spots gives its size. Her measurements also showed that the phosphate backbones are on the outside. The double helix model of Watson and Crick (1953) was built with her data.|Cuando los rayos X atraviesan fibras de ADN, se dispersan y dejan un dibujo en la película fotográfica. La cruz en forma de X de la Foto 51 es la firma de una hélice, y la separación de las manchas da su tamaño. Sus medidas también mostraron que las cadenas de fosfatos están por fuera. El modelo de doble hélice de Watson y Crick (1953) se construyó con sus datos.|Quand les rayons X traversent des fibres d'ADN, ils sont diffusés et laissent un motif sur le film photographique. La croix en X de la photo 51 est la signature d'une hélice, et l'écart entre les taches en donne la taille. Ses mesures ont aussi montré que les chaînes de phosphates sont à l'extérieur. Le modèle en double hélice de Watson et Crick (1953) a été construit avec ses données.|Quan els raigs X travessen fibres d'ADN, es dispersen i deixen un dibuix a la pel·lícula fotogràfica. La creu en forma de X de la Foto 51 és la signatura d'una hèlix, i la separació de les taques en dona la mida. Les seves mesures també van mostrar que les cadenes de fosfats són per fora. El model de doble hèlix de Watson i Crick (1953) es va construir amb les seves dades."),
            Txt.Of("Her own draft of the 1953 article, dated 17 March 1953 — before she knew about the Watson-Crick model — shows that she was already preparing to publish her results on the B form of DNA.|Su propio borrador del artículo de 1953, fechado el 17 de marzo de 1953 —antes de conocer el modelo de Watson y Crick—, muestra que ya preparaba la publicación de sus resultados sobre la forma B del ADN.|Son propre brouillon de l'article de 1953, daté du 17 mars 1953 — avant qu'elle ne connaisse le modèle de Watson et Crick —, montre qu'elle préparait déjà la publication de ses résultats sur la forme B de l'ADN.|El seu propi esborrany de l'article de 1953, datat el 17 de març de 1953 —abans de conèixer el model de Watson i Crick—, mostra que ja preparava la publicació dels seus resultats sobre la forma B de l'ADN."),
            Txt.Of("Watson, Crick and Wilkins received the Nobel Prize in 1962; Franklin had died in 1958, and the prize is not given after death.|Watson, Crick y Wilkins recibieron el Premio Nobel en 1962; Franklin había muerto en 1958, y el premio no se da a título póstumo.|Watson, Crick et Wilkins ont reçu le prix Nobel en 1962 ; Franklin était morte en 1958, et le prix n'est pas décerné à titre posthume.|Watson, Crick i Wilkins van rebre el Premi Nobel el 1962; Franklin havia mort el 1958, i el premi no es dona a títol pòstum."),
            [S("Rough draft of her 1953 DNA article (Papers of Rosalind Franklin)|Borrador de su artículo sobre el ADN de 1953 (archivo de Rosalind Franklin)|Brouillon de son article de 1953 sur l'ADN (archives de Rosalind Franklin)|Esborrany del seu article sobre l'ADN de 1953 (arxiu de Rosalind Franklin)", "U.S. National Library of Medicine", "https://collections.nlm.nih.gov/catalog/nlm:nlmuid-101584586X136-doc"),
             S("About the 1953 article and Photo 51|Sobre el artículo de 1953 y la Foto 51|À propos de l'article de 1953 et de la photo 51|Sobre l'article de 1953 i la Foto 51", "Embryo Project (Arizona State University)", "https://embryo.asu.edu/pages/molecular-configuration-sodium-thymonucleate-1953-rosalind-franklin-and-raymond-gosling")]),
        new("ibnbattuta",
            [E(1304, "Born in Tangier (Morocco)|Nace en Tánger (Marruecos)|Naît à Tanger (Maroc)|Neix a Tànger (Marroc)"), E(1325, "Leaves for the pilgrimage to Mecca|Parte en peregrinación a La Meca|Part en pèlerinage à La Mecque|Surt en pelegrinatge a la Meca"),
             E(1334, "Arrives in Delhi, where he works as a judge|Llega a Delhi, donde trabaja como juez|Arrive à Delhi, où il devient juge|Arriba a Delhi, on treballa com a jutge"), E(1345, "Travels to China|Viaja a China|Voyage en Chine|Viatja a la Xina"),
             E(1352, "Crosses the Sahara to the Mali Empire|Cruza el Sáhara hasta el Imperio de Malí|Traverse le Sahara jusqu'à l'empire du Mali|Travessa el Sàhara fins a l'Imperi de Mali"), E(1355, "Dictates the Rihla to Ibn Juzayy in Fez|Dicta la Rihla a Ibn Yuzayy en Fez|Dicte la Rihla à Ibn Juzayy à Fès|Dicta la Rihla a Ibn Juzayy a Fes")],
            Txt.Of("For almost thirty years Ibn Battuta crossed North Africa, the Middle East, India, the Maldives, China and West Africa. His book describes cities, markets, foods, customs and rulers of the 14th century world. For historians it is a unique source about places that few other writers described.|Durante casi treinta años, Ibn Battuta recorrió el norte de África, Oriente Medio, la India, las Maldivas, China y África occidental. Su libro describe ciudades, mercados, comidas, costumbres y gobernantes del mundo del siglo XIV. Para los historiadores es una fuente única sobre lugares que pocos escritores describieron.|Pendant près de trente ans, Ibn Battuta a parcouru l'Afrique du Nord, le Moyen-Orient, l'Inde, les Maldives, la Chine et l'Afrique de l'Ouest. Son livre décrit les villes, les marchés, les plats, les coutumes et les souverains du monde du XIVᵉ siècle. Pour les historiens, c'est une source unique sur des lieux que peu d'auteurs ont décrits.|Durant gairebé trenta anys, Ibn Battuta va recórrer el nord d'Àfrica, l'Orient Mitjà, l'Índia, les Maldives, la Xina i l'Àfrica occidental. El seu llibre descriu ciutats, mercats, menjars, costums i governants del món del segle XIV. Per als historiadors és una font única sobre llocs que pocs escriptors van descriure."),
            Txt.Of("Manuscripts of the Rihla, copied by hand in Arabic, survive in several libraries. The Library of Congress shows one of them, with the full title \"A Gift to Those Who Contemplate the Wonders of Cities and the Marvels of Travelling\".|Se conservan manuscritos de la Rihla, copiados a mano en árabe, en varias bibliotecas. La Biblioteca del Congreso de EE. UU. muestra uno, con el título completo «Un regalo para quienes contemplan las maravillas de las ciudades y los prodigios de los viajes».|Des manuscrits de la Rihla, copiés à la main en arabe, sont conservés dans plusieurs bibliothèques. La Bibliothèque du Congrès américain en montre un, avec le titre complet « Un cadeau pour ceux qui contemplent les merveilles des villes et les prodiges des voyages ».|Es conserven manuscrits de la Rihla, copiats a mà en àrab, en diverses biblioteques. La Biblioteca del Congrés dels EUA en mostra un, amb el títol complet «Un regal per als qui contemplen les meravelles de les ciutats i els prodigis dels viatges»."),
            Txt.Of("Ibn Battuta travelled much more than Marco Polo, who lived a few decades earlier.|Ibn Battuta viajó mucho más que Marco Polo, que vivió unas décadas antes.|Ibn Battuta a voyagé beaucoup plus que Marco Polo, qui avait vécu quelques décennies plus tôt.|Ibn Battuta va viatjar molt més que Marco Polo, que va viure unes dècades abans."),
            [S("Ibn Battuta's Rihla, Arabic manuscript|La Rihla de Ibn Battuta, manuscrito árabe|La Rihla d'Ibn Battuta, manuscrit arabe|La Rihla d'Ibn Battuta, manuscrit àrab", "Library of Congress", "https://lccn.loc.gov/2021666192"),
             S("The first English translation (1829), public domain|La primera traducción al inglés (1829), de dominio público|La première traduction anglaise (1829), domaine public|La primera traducció a l'anglès (1829), de domini públic", "Wellcome Collection", "https://wellcomecollection.org/works/vvpem8g6")]),
        new("smith",
            [E(1723, "Born in Kirkcaldy (Scotland)|Nace en Kirkcaldy (Escocia)|Naît à Kirkcaldy (Écosse)|Neix a Kirkcaldy (Escòcia)"), E(1751, "Professor at the University of Glasgow|Profesor en la Universidad de Glasgow|Professeur à l'université de Glasgow|Professor a la Universitat de Glasgow"),
             E(1759, "Publishes The Theory of Moral Sentiments|Publica La teoría de los sentimientos morales|Publie la Théorie des sentiments moraux|Publica La teoria dels sentiments morals"), E(1764, "Travels in France and meets French economists|Viaja por Francia y conoce a economistas franceses|Voyage en France et rencontre des économistes français|Viatja per França i coneix economistes francesos"),
             E(1776, "Publishes The Wealth of Nations|Publica La riqueza de las naciones|Publie La Richesse des nations|Publica La riquesa de les nacions"), E(1790, "Dies in Edinburgh|Muere en Edimburgo|Meurt à Édimbourg|Mor a Edimburg")],
            Txt.Of("In a pin factory, one worker alone could hardly make 20 pins a day. When the work is split into about 18 small steps (pulling the wire, straightening, cutting, sharpening…), ten workers make about 48,000 a day. Smith showed that the division of labour and trade between people make countries richer, and he also wrote about fair rules for markets.|En una fábrica de alfileres, un obrero solo apenas haría 20 alfileres al día. Si el trabajo se reparte en unos 18 pasos pequeños (estirar el alambre, enderezarlo, cortarlo, afilarlo…), diez obreros fabrican unos 48 000 al día. Smith mostró que la división del trabajo y el comercio hacen más ricos a los países, y también escribió sobre normas justas para los mercados.|Dans une fabrique d'épingles, un ouvrier seul ferait à peine 20 épingles par jour. Si le travail est découpé en environ 18 petites étapes (tirer le fil, le dresser, le couper, l'aiguiser…), dix ouvriers en fabriquent environ 48 000 par jour. Smith a montré que la division du travail et l'échange enrichissent les pays, et il a aussi écrit sur des règles justes pour les marchés.|En una fàbrica d'agulles, un obrer sol amb prou feines en faria 20 al dia. Si la feina es reparteix en uns 18 passos petits (estirar el filferro, adreçar-lo, tallar-lo, esmolar-lo…), deu obrers en fabriquen uns 48 000 al dia. Smith va mostrar que la divisió del treball i el comerç enriqueixen els països, i també va escriure sobre normes justes per als mercats."),
            Txt.Of("The pin factory example is in the first chapter of The Wealth of Nations (1776), which can be read in full and free of charge.|El ejemplo de la fábrica de alfileres está en el primer capítulo de La riqueza de las naciones (1776), que se puede leer completa y gratis.|L'exemple de la fabrique d'épingles se trouve au premier chapitre de La Richesse des nations (1776), qui se lit en entier et gratuitement.|L'exemple de la fàbrica d'agulles és al primer capítol de La riquesa de les nacions (1776), que es pot llegir sencera i de franc."),
            Txt.Of("Smith's portrait appeared on the British £20 note from 2007 to 2020.|El retrato de Smith apareció en el billete británico de 20 libras de 2007 a 2020.|Le portrait de Smith a figuré sur le billet britannique de 20 livres de 2007 à 2020.|El retrat de Smith va aparèixer al bitllet britànic de 20 lliures del 2007 al 2020."),
            [S("The Wealth of Nations (1776), full text|La riqueza de las naciones (1776), texto completo|La Richesse des nations (1776), texte intégral|La riquesa de les nacions (1776), text complet", "Project Gutenberg", "https://www.gutenberg.org/ebooks/3300")]),
        new("noether",
            [E(1882, "Born in Erlangen (Germany)|Nace en Erlangen (Alemania)|Naît à Erlangen (Allemagne)|Neix a Erlangen (Alemanya)"), E(1907, "Doctorate in mathematics|Doctorado en matemáticas|Doctorat en mathématiques|Doctorat en matemàtiques"),
             E(1915, "Invited to Göttingen by Hilbert and Klein|Invitada a Gotinga por Hilbert y Klein|Invitée à Göttingen par Hilbert et Klein|Convidada a Göttingen per Hilbert i Klein"), E(1918, "Proves Noether's theorem|Demuestra el teorema de Noether|Démontre le théorème de Noether|Demostra el teorema de Noether"),
             E(1933, "Dismissed by the Nazi government, goes to the United States|Expulsada por el gobierno nazi, se va a Estados Unidos|Renvoyée par le gouvernement nazi, part aux États-Unis|Expulsada pel govern nazi, se'n va als Estats Units"), E(1935, "Dies in Bryn Mawr (USA)|Muere en Bryn Mawr (EE. UU.)|Meurt à Bryn Mawr (États-Unis)|Mor a Bryn Mawr (EUA)")],
            Txt.Of("A symmetry is something you can change without changing the result. If an experiment works the same today or tomorrow (symmetry in time), energy is conserved; if it works the same here or a metre away (symmetry in space), momentum is conserved; if it works the same when you turn it (rotation), angular momentum is conserved. Noether proved that every such symmetry gives a conservation law.|Una simetría es algo que puedes cambiar sin que cambie el resultado. Si un experimento funciona igual hoy que mañana (simetría en el tiempo), la energía se conserva; si funciona igual aquí que un metro más allá (simetría en el espacio), se conserva el momento lineal; si funciona igual al girarlo (rotación), se conserva el momento angular. Noether demostró que cada simetría así da una ley de conservación.|Une symétrie, c'est quelque chose qu'on peut changer sans changer le résultat. Si une expérience marche pareil aujourd'hui et demain (symétrie dans le temps), l'énergie se conserve ; pareil ici ou un mètre plus loin (symétrie dans l'espace), la quantité de mouvement se conserve ; pareil quand on la tourne (rotation), le moment cinétique se conserve. Noether a démontré qu'à chaque symétrie de ce genre correspond une loi de conservation.|Una simetria és una cosa que pots canviar sense que canviï el resultat. Si un experiment funciona igual avui que demà (simetria en el temps), l'energia es conserva; si funciona igual aquí que un metre més enllà (simetria en l'espai), es conserva el moment lineal; si funciona igual quan el gires (rotació), es conserva el moment angular. Noether va demostrar que cada simetria d'aquest tipus dona una llei de conservació."),
            Txt.Of("Her 1918 article \"Invariante Variationsprobleme\", presented at Göttingen by Felix Klein, can be read in an English translation.|Su artículo de 1918 «Invariante Variationsprobleme», presentado en Gotinga por Felix Klein, se puede leer en una traducción al inglés.|Son article de 1918, « Invariante Variationsprobleme », présenté à Göttingen par Felix Klein, se lit dans une traduction anglaise.|El seu article de 1918 «Invariante Variationsprobleme», presentat a Göttingen per Felix Klein, es pot llegir en una traducció a l'anglès."),
            Txt.Of("In 1935 Einstein wrote that she was the most important creative mathematical genius since women began to have higher education.|En 1935 Einstein escribió que había sido el genio matemático creativo más importante desde que las mujeres accedieron a la educación superior.|En 1935, Einstein a écrit qu'elle avait été le génie mathématique créatif le plus important depuis que les femmes ont accès aux études supérieures.|El 1935 Einstein va escriure que havia estat el geni matemàtic creatiu més important des que les dones van accedir a l'educació superior."),
            [S("Invariant Variation Problems (1918), English translation|«Invariant Variation Problems» (1918), traducción al inglés|« Invariant Variation Problems » (1918), traduction anglaise|«Invariant Variation Problems» (1918), traducció a l'anglès", "arXiv", "https://arxiv.org/abs/physics/0503066")]),
        new("champollion",
            [E(1790, "Born in Figeac (France)|Nace en Figeac (Francia)|Naît à Figeac (France)|Neix a Figeac (França)"), E(1799, "French soldiers find the Rosetta Stone in Egypt|Soldados franceses encuentran la piedra de Rosetta en Egipto|Des soldats français trouvent la pierre de Rosette en Égypte|Soldats francesos troben la pedra de Rosetta a Egipte"),
             E(1802, "The stone goes on display at the British Museum|La piedra se expone en el British Museum|La pierre est exposée au British Museum|La pedra s'exposa al British Museum"), E(1822, "Announces the decipherment of hieroglyphs (Letter to M. Dacier)|Anuncia el desciframiento de los jeroglíficos (Carta a M. Dacier)|Annonce le déchiffrement des hiéroglyphes (Lettre à M. Dacier)|Anuncia el desxiframent dels jeroglífics (Carta a M. Dacier)"),
             E(1828, "Travels along the Nile|Viaja por el Nilo|Remonte le Nil|Viatja pel Nil"), E(1832, "Dies in Paris|Muere en París|Meurt à Paris|Mor a París")],
            Txt.Of("The Rosetta Stone (196 BC) repeats one decree in three scripts: hieroglyphs, demotic and Greek. Royal names are inside ovals called cartouches. Comparing the cartouche of Ptolemy with the Greek name, Champollion matched signs with sounds (P, T, O, L, M, Y, S), then checked them with Cleopatra. He understood that hieroglyphs mix signs for sounds and signs for ideas.|La piedra de Rosetta (196 a. C.) repite un decreto en tres escrituras: jeroglíficos, demótico y griego. Los nombres de los reyes están dentro de óvalos llamados cartuchos. Comparando el cartucho de Ptolomeo con el nombre griego, Champollion relacionó signos con sonidos (P, T, O, L, M, Y, S) y luego los comprobó con Cleopatra. Entendió que los jeroglíficos mezclan signos de sonidos y signos de ideas.|La pierre de Rosette (196 av. J.-C.) répète un même décret en trois écritures : hiéroglyphes, démotique et grec. Les noms des rois sont dans des ovales appelés cartouches. En comparant le cartouche de Ptolémée avec le nom grec, Champollion a associé des signes à des sons (P, T, O, L, M, Y, S), puis les a vérifiés avec Cléopâtre. Il a compris que les hiéroglyphes mêlent des signes de sons et des signes d'idées.|La pedra de Rosetta (196 aC) repeteix un decret en tres escriptures: jeroglífics, demòtic i grec. Els noms dels reis són dins d'ovals anomenats cartutxos. Comparant el cartutx de Ptolemeu amb el nom grec, Champollion va relacionar signes amb sons (P, T, O, L, M, Y, S) i després els va comprovar amb Cleòpatra. Va entendre que els jeroglífics barregen signes de sons i signes d'idees."),
            Txt.Of("The Rosetta Stone itself is in the British Museum (number EA24): 14 lines of hieroglyphs, 32 of demotic and 54 of Greek.|La propia piedra de Rosetta está en el British Museum (número EA24): 14 líneas de jeroglíficos, 32 de demótico y 54 de griego.|La pierre de Rosette elle-même est au British Museum (numéro EA24) : 14 lignes de hiéroglyphes, 32 de démotique et 54 de grec.|La mateixa pedra de Rosetta és al British Museum (número EA24): 14 línies de jeroglífics, 32 de demòtic i 54 de grec."),
            Txt.Of("The Rosetta Stone is the most visited object of the British Museum.|La piedra de Rosetta es el objeto más visitado del British Museum.|La pierre de Rosette est l'objet le plus visité du British Museum.|La pedra de Rosetta és l'objecte més visitat del British Museum."),
            [S("The Rosetta Stone (EA24)|La piedra de Rosetta (EA24)|La pierre de Rosette (EA24)|La pedra de Rosetta (EA24)", "British Museum", "https://www.britishmuseum.org/collection/object/Y_EA24")]),
        new("einstein",
            [E(1879, "Born in Ulm (Germany)|Nace en Ulm (Alemania)|Naît à Ulm (Allemagne)|Neix a Ulm (Alemanya)"), E(1905, "\"Miracle year\": publishes relativity and E=mc² while working at a patent office|\"Año milagroso\": publica la relatividad y E=mc² mientras trabaja en una oficina de patentes|« Année miraculeuse » : publie la relativité et E=mc² alors qu'il travaille dans un bureau des brevets|\"Any miracle\": publica la relativitat i E=mc² mentre treballa en una oficina de patents"),
             E(1919, "A solar eclipse confirms his prediction that gravity bends light|Un eclipse solar confirma su predicción de que la gravedad curva la luz|Une éclipse solaire confirme sa prédiction selon laquelle la gravité courbe la lumière|Un eclipsi solar confirma la seva predicció que la gravetat corba la llum"),
             E(1921, "Nobel Prize in Physics, for the photoelectric effect|Premio Nobel de Física, por el efecto fotoeléctrico|Prix Nobel de physique, pour l'effet photoélectrique|Premi Nobel de Física, per l'efecte fotoelèctric"), E(1933, "Leaves Germany for the United States|Se va de Alemania a Estados Unidos|Quitte l'Allemagne pour les États-Unis|Marxa d'Alemanya cap als Estats Units"), E(1955, "Dies in Princeton (USA)|Muere en Princeton (EE. UU.)|Meurt à Princeton (États-Unis)|Mor a Princeton (EUA)")],
            Txt.Of("In 1905, while working at a Swiss patent office rather than a university, Einstein published several papers that changed physics: one showed that light comes in packets of energy, one showed that time and space depend on how fast you move, and one gave the equation E=mc². Ten years later he extended these ideas into general relativity, where gravity is the bending of space and time around mass.|En 1905, mientras trabajaba en una oficina de patentes suiza y no en una universidad, Einstein publicó varios artículos que cambiaron la física: uno mostraba que la luz llega en paquetes de energía, otro que el tiempo y el espacio dependen de lo rápido que te mueves, y otro daba la ecuación E=mc². Diez años después extendió estas ideas a la relatividad general, donde la gravedad es la curvatura del espacio y el tiempo alrededor de la masa.|En 1905, alors qu'il travaillait dans un bureau des brevets suisse plutôt qu'à l'université, Einstein a publié plusieurs articles qui ont changé la physique : l'un montrait que la lumière arrive par paquets d'énergie, un autre que le temps et l'espace dépendent de la vitesse à laquelle on se déplace, et un autre donnait l'équation E=mc². Dix ans plus tard, il a étendu ces idées à la relativité générale, où la gravité est la courbure de l'espace et du temps autour de la masse.|El 1905, mentre treballava en una oficina de patents suïssa i no en una universitat, Einstein va publicar diversos articles que van canviar la física: un mostrava que la llum arriba en paquets d'energia, un altre que el temps i l'espai depenen de com de ràpid et mous, i un altre donava l'equació E=mc². Deu anys després va estendre aquestes idees a la relativitat general, on la gravetat és la corbatura de l'espai i el temps al voltant de la massa."),
            Txt.Of("In 1919, astronomers led by Arthur Eddington photographed stars near the Sun during a total eclipse and found their light was bent by exactly the amount Einstein's general relativity predicted, as the Royal Society later retold.|En 1919, astrónomos liderados por Arthur Eddington fotografiaron estrellas cerca del Sol durante un eclipse total y comprobaron que su luz se curvaba justo la cantidad que predecía la relatividad general de Einstein, como contó después la Royal Society.|En 1919, des astronomes dirigés par Arthur Eddington ont photographié des étoiles près du Soleil pendant une éclipse totale et ont constaté que leur lumière était courbée exactement de la quantité prédite par la relativité générale d'Einstein, comme la Royal Society l'a raconté ensuite.|El 1919, astrònoms dirigits per Arthur Eddington van fotografiar estrelles a prop del Sol durant un eclipsi total i van comprovar que la seva llum es corbava exactament la quantitat que predeia la relativitat general d'Einstein, tal com va explicar després la Royal Society."),
            Txt.Of("Einstein won the Nobel Prize for the photoelectric effect, not for relativity, which was still considered too new and debated at the time.|Einstein ganó el Premio Nobel por el efecto fotoeléctrico, no por la relatividad, que entonces aún se consideraba demasiado nueva y debatida.|Einstein a reçu le prix Nobel pour l'effet photoélectrique, et non pour la relativité, encore jugée trop nouvelle et débattue à l'époque.|Einstein va guanyar el premi Nobel per l'efecte fotoelèctric, no per la relativitat, que aleshores encara es considerava massa nova i debatuda."),
            [S("Nobel Prize in Physics 1921: the official record|Premio Nobel de Física 1921: el registro oficial|Prix Nobel de physique 1921 : la fiche officielle|Premi Nobel de Física 1921: el registre oficial", "NobelPrize.org", "https://www.nobelprize.org/prizes/physics/1921/einstein/facts/"),
             S("Observing relativity: the 1919 eclipse expedition|Observando la relatividad: la expedición del eclipse de 1919|Observer la relativité : l'expédition de l'éclipse de 1919|Observant la relativitat: l'expedició de l'eclipsi de 1919", "The Royal Society", "https://royalsociety.org/blog/2024/08/observing-relativity")]),
        new("shakespeare",
            [E(1564, "Born in Stratford-upon-Avon (England)|Nace en Stratford-upon-Avon (Inglaterra)|Naît à Stratford-upon-Avon (Angleterre)|Neix a Stratford-upon-Avon (Anglaterra)"), E(1582, "Marries Anne Hathaway|Se casa con Anne Hathaway|Épouse Anne Hathaway|Es casa amb Anne Hathaway"),
             E(1594, "Joins the Lord Chamberlain's Men acting company|Se une a la compañía Lord Chamberlain's Men|Rejoint la troupe des Lord Chamberlain's Men|S'uneix a la companyia Lord Chamberlain's Men"), E(1599, "The Globe Theatre opens in London|Se inaugura el teatro The Globe en Londres|Le théâtre du Globe ouvre à Londres|S'inaugura el teatre The Globe a Londres"),
             E(1609, "His sonnets are published|Se publican sus sonetos|Ses sonnets sont publiés|Es publiquen els seus sonets"), E(1616, "Dies in Stratford-upon-Avon|Muere en Stratford-upon-Avon|Meurt à Stratford-upon-Avon|Mor a Stratford-upon-Avon")],
            Txt.Of("Shakespeare's plays mix comedy, tragedy and history, and give even minor characters their own believable voice, something unusual for the stage of his time. In plays like Hamlet, long private speeches let the audience hear a character think out loud about life, death and doubt, which helped invent a new way of showing someone's inner mind on stage.|Las obras de Shakespeare mezclan comedia, tragedia e historia, y dan incluso a los personajes secundarios una voz propia y creíble, algo poco habitual en el teatro de su época. En obras como Hamlet, largos monólogos dejan que el público oiga a un personaje pensar en voz alta sobre la vida, la muerte y la duda, lo que ayudó a inventar una nueva forma de mostrar la mente interior de alguien en el escenario.|Les pièces de Shakespeare mêlent comédie, tragédie et histoire, et donnent même aux personnages secondaires une voix propre et crédible, chose inhabituelle pour le théâtre de son époque. Dans des pièces comme Hamlet, de longs monologues laissent le public entendre un personnage réfléchir à voix haute sur la vie, la mort et le doute, ce qui a aidé à inventer une nouvelle façon de montrer l'esprit intérieur de quelqu'un sur scène.|Les obres de Shakespeare barregen comèdia, tragèdia i història, i donen fins i tot als personatges secundaris una veu pròpia i creïble, cosa poc habitual al teatre de la seva època. En obres com Hamlet, llargs monòlegs deixen que el públic senti un personatge pensar en veu alta sobre la vida, la mort i el dubte, cosa que va ajudar a inventar una nova manera de mostrar la ment interior d'algú a l'escenari."),
            Txt.Of("Seven years after his death, his fellow actors John Heminges and Henry Condell collected 36 of his plays into one book, the First Folio (1623); without it, about half of his plays, including Macbeth, might never have survived. The Bodleian Library's copy has been fully digitised and can be read page by page online.|Siete años después de su muerte, sus compañeros de compañía John Heminges y Henry Condell reunieron 36 de sus obras en un solo libro, el Primer Folio (1623); sin él, cerca de la mitad de sus obras, incluida Macbeth, quizá no habrían sobrevivido. El ejemplar de la Bodleian Library se ha digitalizado por completo y se puede leer página a página en línea.|Sept ans après sa mort, ses camarades de troupe John Heminges et Henry Condell ont rassemblé 36 de ses pièces en un seul livre, le Premier Folio (1623) ; sans lui, près de la moitié de ses pièces, dont Macbeth, n'auraient peut-être pas survécu. L'exemplaire de la Bodleian Library a été entièrement numérisé et se lit page par page en ligne.|Set anys després de la seva mort, els seus companys de companyia John Heminges i Henry Condell van reunir 36 de les seves obres en un sol llibre, el Primer Foli (1623); sense ell, prop de la meitat de les seves obres, inclosa Macbeth, potser no haurien sobreviscut. L'exemplar de la Bodleian Library s'ha digitalitzat sencer i es pot llegir pàgina a pàgina en línia."),
            Txt.Of("During a performance of Henry VIII in 1613, a cannon effect set fire to the Globe's thatched roof and burned the whole theatre down in under an hour; it was rebuilt the following year.|Durante una representación de Enrique VIII en 1613, un efecto de cañón prendió fuego al tejado de paja del Globe y quemó todo el teatro en menos de una hora; se reconstruyó al año siguiente.|Pendant une représentation de Henri VIII en 1613, un effet de canon a mis le feu au toit de chaume du Globe et a brûlé tout le théâtre en moins d'une heure ; il a été reconstruit l'année suivante.|Durant una representació d'Enric VIII el 1613, un efecte de canó va incendiar la teulada de palla del Globe i va cremar tot el teatre en menys d'una hora; es va reconstruir l'any següent."),
            [S("The Bodleian First Folio, digital facsimile|El Primer Folio de la Bodleian, facsímil digital|Le Premier Folio de la Bodleian, fac-similé numérique|El Primer Foli de la Bodleian, facsímil digital", "Bodleian Library, University of Oxford", "https://firstfolio.bodleian.ox.ac.uk/")]),
        new("goodall",
            [E(1934, "Born in London (England)|Nace en Londres (Inglaterra)|Naît à Londres (Angleterre)|Neix a Londres (Anglaterra)"), E(1960, "Arrives at Gombe, in Tanzania, and sees a chimpanzee use a tool|Llega a Gombe, en Tanzania, y ve a un chimpancé usar una herramienta|Arrive à Gombe, en Tanzanie, et voit un chimpanzé utiliser un outil|Arriba a Gombe, a Tanzània, i veu un ximpanzé fer servir una eina"),
             E(1964, "Publishes her tool-use discovery in the journal Nature|Publica su descubrimiento sobre el uso de herramientas en la revista Nature|Publie sa découverte sur l'usage d'outils dans la revue Nature|Publica el seu descobriment sobre l'ús d'eines a la revista Nature"), E(1965, "Earns a PhD from the University of Cambridge|Se doctora en la Universidad de Cambridge|Obtient un doctorat de l'université de Cambridge|Es doctora a la Universitat de Cambridge"),
             E(1977, "Founds the Jane Goodall Institute|Funda el Instituto Jane Goodall|Fonde le Jane Goodall Institute|Funda el Jane Goodall Institute"), E(2025, "Dies in Los Angeles (USA), while on a speaking tour|Muere en Los Ángeles (EE. UU.), en una gira de conferencias|Meurt à Los Angeles (États-Unis), lors d'une tournée de conférences|Mor a Los Angeles (EUA), en una gira de conferències")],
            Txt.Of("On 4 November 1960, Jane Goodall watched a chimpanzee she named David Greybeard strip the leaves off a twig and push it into a termite mound to pull out termites to eat. Until then, scientists defined humans as \"the tool-making animal\"; her careful, patient observation showed that was not true, and opened the door to decades of research into how much chimpanzee minds and societies resemble our own.|El 4 de noviembre de 1960, Jane Goodall observó a un chimpancé al que llamó David Greybeard quitarle las hojas a un palito e introducirlo en un hormiguero para sacar termitas y comérselas. Hasta entonces, los científicos definían a los humanos como \"el animal que fabrica herramientas\"; su observación paciente y minuciosa demostró que eso no era cierto, y abrió la puerta a décadas de investigación sobre cuánto se parecen las mentes y las sociedades de los chimpancés a las nuestras.|Le 4 novembre 1960, Jane Goodall a observé un chimpanzé qu'elle avait nommé David Greybeard retirer les feuilles d'une brindille et l'enfoncer dans une termitière pour en retirer des termites à manger. Jusque-là, les scientifiques définissaient les humains comme « l'animal qui fabrique des outils » ; son observation patiente et minutieuse a montré que ce n'était pas vrai, et a ouvert la voie à des décennies de recherche sur à quel point l'esprit et les sociétés des chimpanzés ressemblent aux nôtres.|El 4 de novembre de 1960, Jane Goodall va observar un ximpanzé que havia anomenat David Greybeard treure les fulles d'un branquilló i ficar-lo en un formiguer per treure'n tèrmits i menjar-se'ls. Fins aleshores, els científics definien els humans com \"l'animal que fabrica eines\"; la seva observació pacient i minuciosa va demostrar que allò no era cert, i va obrir la porta a dècades de recerca sobre com s'assemblen la ment i les societats dels ximpanzés a les nostres."),
            Txt.Of("Goodall published her tool-use observations in the scientific journal Nature in 1964, and the Jane Goodall Institute still tells the story of how it changed science, on its own website.|Goodall publicó sus observaciones sobre el uso de herramientas en la revista científica Nature en 1964, y el Instituto Jane Goodall todavía cuenta en su web cómo esto cambió la ciencia.|Goodall a publié ses observations sur l'usage d'outils dans la revue scientifique Nature en 1964, et le Jane Goodall Institute raconte encore sur son site comment cela a changé la science.|Goodall va publicar les seves observacions sobre l'ús d'eines a la revista científica Nature el 1964, i el Jane Goodall Institute encara explica al seu lloc web com això va canviar la ciència."),
            Txt.Of("The chimpanzee community she began studying at Gombe in 1960 has been observed almost every single day since then, making it one of the longest continuous studies of wild animals in the world.|La comunidad de chimpancés que empezó a estudiar en Gombe en 1960 ha sido observada casi todos los días desde entonces, lo que la convierte en uno de los estudios continuos de animales salvajes más largos del mundo.|La communauté de chimpanzés qu'elle a commencé à étudier à Gombe en 1960 a été observée presque tous les jours depuis, ce qui en fait l'une des plus longues études continues d'animaux sauvages au monde.|La comunitat de ximpanzés que va començar a estudiar a Gombe el 1960 ha estat observada gairebé cada dia des de llavors, cosa que la converteix en un dels estudis continus d'animals salvatges més llargs del món."),
            [S("Tool-using and aimed throwing in a community of free-living chimpanzees (1964)|«Tool-using and aimed throwing...» (1964)|« Tool-using and aimed throwing... » (1964)|«Tool-using and aimed throwing...» (1964)", "Nature", "https://www.nature.com/articles/2011264A0"),
             S("How Jane changed science forever|Cómo Jane cambió la ciencia para siempre|Comment Jane a changé la science à jamais|Com Jane va canviar la ciència per sempre", "Jane Goodall Institute", "https://janegoodall.org/?p=14407")]),
        new("mansamusa",
            [E(1280, "Born in the Mali Empire (West Africa)|Nace en el Imperio de Malí (África occidental)|Naît dans l'Empire du Mali (Afrique de l'Ouest)|Neix a l'Imperi de Mali (Àfrica occidental)"), E(1312, "Becomes Mansa (emperor) of Mali|Se convierte en Mansa (emperador) de Malí|Devient Mansa (empereur) du Mali|Es converteix en Mansa (emperador) de Mali"),
             E(1324, "Makes his famous pilgrimage to Mecca|Hace su famosa peregrinación a La Meca|Fait son célèbre pèlerinage à La Mecque|Fa el seu famós pelegrinatge a la Meca"), E(1325, "His empire takes control of the trading city of Timbuktu|Su imperio toma el control de la ciudad comercial de Tombuctú|Son empire prend le contrôle de la ville commerçante de Tombouctou|El seu imperi pren el control de la ciutat comercial de Tombuctu"),
             E(1327, "Commissions the Djinguereber Mosque in Timbuktu|Encarga la mezquita de Djinguereber en Tombuctú|Commande la mosquée de Djingareyber à Tombouctou|Encarrega la mesquita de Djinguereber a Tombuctu"), E(1337, "Dies in the Mali Empire|Muere en el Imperio de Malí|Meurt dans l'Empire du Mali|Mor a l'Imperi de Mali")],
            Txt.Of("Mansa Musa's pilgrimage to Mecca in 1324 crossed the Sahara with a huge caravan said to include thousands of soldiers, attendants and camels loaded with gold. He gave away so much gold along the way, especially in Cairo, that word of his wealth spread across North Africa, the Middle East and eventually Europe, putting the Mali Empire on the map of the known world almost overnight.|La peregrinación de Mansa Musa a La Meca en 1324 cruzó el Sáhara con una enorme caravana que se dice incluía miles de soldados, sirvientes y camellos cargados de oro. Regaló tanto oro por el camino, sobre todo en El Cairo, que la noticia de su riqueza se extendió por el norte de África, Oriente Medio y finalmente Europa, poniendo al Imperio de Malí en el mapa del mundo conocido casi de la noche a la mañana.|Le pèlerinage de Mansa Musa à La Mecque en 1324 a traversé le Sahara avec une immense caravane qui aurait compté des milliers de soldats, de serviteurs et de chameaux chargés d'or. Il a distribué tant d'or en chemin, surtout au Caire, que la nouvelle de sa richesse s'est répandue en Afrique du Nord, au Moyen-Orient puis en Europe, mettant l'Empire du Mali sur la carte du monde connu presque du jour au lendemain.|El pelegrinatge de Mansa Musa a la Meca el 1324 va travessar el Sàhara amb una enorme caravana que es diu que incloïa milers de soldats, servents i camells carregats d'or. Va regalar tant or pel camí, sobretot al Caire, que la notícia de la seva riquesa es va estendre pel nord d'Àfrica, l'Orient Mitjà i finalment Europa, posant l'Imperi de Mali al mapa del món conegut gairebé d'un dia per l'altre."),
            Txt.Of("Just decades after his death, European mapmakers drew Mansa Musa himself, crowned and holding a golden orb, on the Catalan Atlas of 1375, one of the most important maps of the Middle Ages, now digitised by the Bibliothèque nationale de France.|Pocas décadas después de su muerte, los cartógrafos europeos dibujaron al propio Mansa Musa, coronado y con un orbe de oro, en el Atlas catalán de 1375, uno de los mapas más importantes de la Edad Media, hoy digitalizado por la Bibliothèque nationale de France.|Quelques décennies à peine après sa mort, des cartographes européens ont dessiné Mansa Moussa lui-même, couronné et tenant un globe d'or, sur l'Atlas catalan de 1375, l'une des cartes les plus importantes du Moyen Âge, aujourd'hui numérisée par la Bibliothèque nationale de France.|Poques dècades després de la seva mort, cartògrafs europeus van dibuixar el mateix Mansa Musa, coronat i amb un orbe d'or, a l'Atlas català de 1375, un dels mapes més importants de l'edat mitjana, avui digitalitzat per la Bibliothèque nationale de France."),
            Txt.Of("The manuscripts collected in Timbuktu's mosques and schools after Mansa Musa's reign grew into one of Africa's largest libraries, parts of which are now preserved as UNESCO-recognised documentary heritage.|Los manuscritos reunidos en las mezquitas y escuelas de Tombuctú después del reinado de Mansa Musa formaron una de las mayores bibliotecas de África, parte de la cual hoy está reconocida como patrimonio documental por la UNESCO.|Les manuscrits rassemblés dans les mosquées et les écoles de Tombouctou après le règne de Mansa Moussa ont formé l'une des plus grandes bibliothèques d'Afrique, dont une partie est aujourd'hui reconnue comme patrimoine documentaire par l'UNESCO.|Els manuscrits reunits a les mesquites i escoles de Tombuctu després del regnat de Mansa Musa van formar una de les biblioteques més grans d'Àfrica, part de la qual avui està reconeguda com a patrimoni documental per la UNESCO."),
            [S("The Catalan Atlas (1375), digitised manuscript|El Atlas catalán (1375), manuscrito digitalizado|L'Atlas catalan (1375), manuscrit numérisé|L'Atlas català (1375), manuscrit digitalitzat", "Gallica, Bibliothèque nationale de France", "https://gallica.bnf.fr/ark:/12148/btv1b55002481n")]),
    ];

